export const COUNTRIES: CountryShape[] = RAW.map(([name, lat, lon, span, enc]) => ({
  name,
  lat,
  lon,
  span,
  rings: enc.map((d) => {
    const r: number[] = [];
    let x = 0;
    let y = 0;
    for (let i = 0; i < d.length; i += 2) {
      x += d[i];
      y += d[i + 1];
      r.push(x / 100, y / 100);
    }
    return r;
  }),
}));
